1	/**
2	 * Signature PNG validation helpers.
3	 * Called on the server before passing base64 to Supabase Storage.
4	 */
5	import type { SupabaseClient } from '@supabase/supabase-js'
6	import type { Database } from '@/lib/supabase/types'
7	
8	const MAX_SIGNATURE_BYTES = 500 * 1024  // 500 KB
9	const VALID_PNG_PREFIX = 'data:image/png;base64,'
10	
11	export interface SignatureValidationResult {
12	  valid: boolean
13	  error?: string
14	  buffer?: Buffer
15	}
16	
17	/**
18	 * Validate that a base64 string is a genuine PNG under 500 KB.
19	 * Returns the decoded Buffer for immediate upload.
20	 */
21	export function validateSignatureBase64(
22	  base64: string,
23	  fieldName = 'signature'
24	): SignatureValidationResult {
25	  if (!base64) {
26	    return { valid: false, error: `${fieldName} is required` }
27	  }
28	
29	  // Accept with or without the data: prefix
30	  let raw = base64
31	  if (raw.startsWith('data:')) {
32	    if (!raw.startsWith(VALID_PNG_PREFIX)) {
33	      return { valid: false, error: `${fieldName} must be a PNG image` }
34	    }
35	    raw = raw.slice(VALID_PNG_PREFIX.length)
36	  }
37	
38	  // Verify it's valid base64
39	  if (!/^[A-Za-z0-9+/]*={0,2}$/.test(raw)) {
40	    return { valid: false, error: `${fieldName} contains invalid base64 characters` }
41	  }
42	
43	  let buffer: Buffer
44	  try {
45	    buffer = Buffer.from(raw, 'base64')
46	  } catch {
47	    return { valid: false, error: `${fieldName} could not be decoded` }
48	  }
49	
50	  // Verify PNG magic bytes: 89 50 4E 47 0D 0A 1A 0A
51	  if (
52	    buffer.length < 8 ||
53	    buffer[0] !== 0x89 ||
54	    buffer[1] !== 0x50 ||
55	    buffer[2] !== 0x4e ||
56	    buffer[3] !== 0x47
57	  ) {
58	    return { valid: false, error: `${fieldName} is not a valid PNG file` }
59	  }
60	
61	  if (buffer.length > MAX_SIGNATURE_BYTES) {
62	    return {
63	      valid: false,
64	      error: `${fieldName} exceeds the 500 KB maximum size (${(buffer.length / 1024).toFixed(0)} KB)`,
65	    }
66	  }
67	
68	  return { valid: true, buffer }
69	}
70	
71	/**
72	 * Upload a validated signature buffer to Supabase Storage.
73	 * Uses the service-role client to bypass RLS.
74	 * Path convention: {studio_id}/{submission_id}/{filename}.png
75	 */
76	export async function uploadSignaturePng(
77	  serviceRoleClient: SupabaseClient<Database>,
78	  buffer: Buffer,
79	  storagePath: string
80	): Promise<void> {
81	  const { error } = await serviceRoleClient.storage
82	    .from('consent-forms')
83	    .upload(storagePath, buffer, {
84	      contentType: 'image/png',
85	      upsert: true,
86	    })
87	
88	  if (error) {
89	    throw new Error(`Signature upload failed at ${storagePath}: ${error.message}`)
90	  }
91	}
