import type { Metadata } from 'next'

export const metadata: Metadata = {
  title: 'Consent Form',
}

/**
 * Isolated public layout for the /consent/* routes.
 * Zero InkOS chrome — no sidebar, no header, no auth check.
 * Studio brand is injected via CSS custom properties set in individual pages.
 */
export default function ConsentLayout({ children }: { children: React.ReactNode }) {
  return (
    <div className="min-h-dvh bg-background antialiased">
      {children}
    </div>
  )
}
